mapper.select:
SELECT t1.`id`, t1.`identify_id`, t1.`vehicle_no`, t1.`access_type`, t1.`channel_no`, t1.`channel_name`, t1.`access_time`, t1.`image_url`, t1.`image_base`, t1.`parking_info_code`, t1.`parking_info_name` FROM `parking_access_record` t1 LEFT JOIN `parking_access_record` t2 ON t1.`identify_id` = t2.`identify_id` AND t2.`access_type` = 'ACCESS_OUT'
t1.`access_type` = 'ACCESS_IN' AND t2.`id` is NULL
and t1.`vehicle_no` like concat('%',#{param.keyword},'%')
and t1.`access_time` >= #{param.period.begin}
and t1.`access_time` <= #{param.period.end}
and t1.`parking_info_code` in
#{parkingInfoCode}
order by t1.`access_time` desc

SELECT
COUNT(t1.id) as `access_num`
FROM
`parking_access_record` t1


        and t1.`access_type` = #{accessType}


        and t1.`access_time` >= #{period.begin}


        and t1.`access_time` <= #{period.end}


        and t1.`parking_info_code` in

            #{parkingInfoCode}

SELECT
    HOUR(t1.`access_time`) AS `name`,
    COUNT(*) AS `valus`
FROM `parking_access_record` t1


        AND t1.`access_type` = #{accessType}


        AND t1.`access_time` >= #{period.begin}


        AND t1.`access_time` < #{period.end}


        AND t1.`parking_info_code` IN

            #{parkingInfoCode}



GROUP BY HOUR(t1.`access_time`)
ORDER BY `name`

SELECT t1.`access_type` AS `accessType`, HOUR(t1.`access_time`) AS `hourOfDay`, COUNT(*) AS `count` FROM `parking_access_record` t1
t1.`access_type` IN ('ACCESS_IN', 'ACCESS_OUT')
AND t1.`access_time` >= #{period.begin}
AND t1.`access_time` < #{period.end}
AND t1.`parking_info_code` IN
#{parkingInfoCode}
GROUP BY t1.`access_type`, HOUR(t1.`access_time`)
